# tandem repeat search: for each period p, find runs of repeating unit
def tandem(seq, min_unit=2, max_unit=12, min_copies=3):
    n=len(seq); found=[]
    for p in range(min_unit,max_unit+1):
        i=0
        while i+p*min_copies<=n:
            unit=seq[i:i+p]
            c=1
            j=i+p
            while seq[j:j+p]==unit:
                c+=1; j+=p
            if c>=min_copies:
                found.append((i,j,p,c,unit))
                i=j
            else:
                i+=1
    return found
